398	/// Resolve `-l` / `-L` flags into a `Header`.
399	///
400	/// `-L` (no header) takes precedence over `-l` (label decoration).
401	pub fn resolve_header(label: &str, suppress: bool) -> Header {
402	    if suppress {
403	        Header::None
404	    } else {
405	        Header::Label(label.to_string())
406	    }
