465	pub fn load_repo(
466	    path: &Path,
467	) -> Result<(Workspace, Arc<ReadonlyRepo>), Box<dyn std::error::Error>> {
468	    let config = StackedConfig::with_defaults();
469	    let settings = UserSettings::from_config(config)?;
470	    let store_factories = StoreFactories::default();
471	    let working_copy_factories = default_working_copy_factories();
472	
473	    let workspace = Workspace::load(&settings, path, &store_factories, &working_copy_factories)?;
474	    let repo = workspace.repo_loader().load_at_head().block_on()?;
475	
476	    Ok((workspace, repo))
477	}
