526	/// Scan `jj bookmark list -a <name>` output for non-tracking remote refs.
527	///
528	/// Tracked remotes appear indented (`  @origin: ...`); non-tracking remotes
529	/// appear at column 0 as `<bookmark>@<remote>: ...`. Returns the
530	/// non-tracking remote name if any is found.
531	pub fn find_non_tracking_remote(list_output: &str, bookmark: &str) -> Option<String> {
532	    let prefix = format!("{bookmark}@");
533	    for line in list_output.lines() {
534	        if line.starts_with(&prefix)
535	            && let Some(rest) = line.strip_prefix(&prefix)
536	            && let Some((remote, _)) = rest.split_once(':')
537	        {
538	            return Some(remote.to_string());
539	        }
540	    }
541	    None
542	}
543	
544	/// Scan `jj bookmark list -a <name>` output for a *tracked* entry
545	/// for `remote`.
546	///
547	/// - Tracked remotes appear indented under the local bookmark —
548	///   `  @origin: ...` when synced, or the decorated divergent form
549	///   `  @origin (ahead by N commits): ...`; both count as tracking.
550	/// - A column-0 `<bookmark>@<remote>: ...` line is a non-tracking
551	///   ref (see `find_non_tracking_remote`), never a match here.
552	pub fn find_tracked_remote(list_output: &str, remote: &str) -> bool {
553	    let colon = format!("@{remote}:");
554	    let space = format!("@{remote} ");
555	    list_output.lines().any(|line| {
556	        line.starts_with(char::is_whitespace) && {
557	            let t = line.trim_start();
558	            t.starts_with(&colon) || t.starts_with(&space)
559	        }
560	    })
561	}
562	
563	/// Verify all remote refs for `bookmark` in `repo` are tracked.
564	///
565	/// Returns `Err` with the exact `jj bookmark track ...` remediation command if
566	/// any non-tracking remote ref is found. Used as a preflight by repo-modifying
567	/// commands (sync, push, squash-push) and as a post-condition assertion by setup
568	/// commands (init, clone, test-fixture).
569	pub fn verify_tracking(repo: &Path, bookmark: &str) -> Result<(), Box<dyn std::error::Error>> {
570	    let all = crate::jj::bookmark_list_all(repo, bookmark)?;
571	    if let Some(remote) = find_non_tracking_remote(&all, bookmark) {
572	        let repo_str = repo.to_string_lossy();
573	        return Err(format!(
574	            "bookmark '{bookmark}' has non-tracking remote '{bookmark}@{remote}' — \
575	             run `jj bookmark track {bookmark} --remote={remote} -R {repo_str}` to fix"
576	        )
577	        .into());
578	    }
579	    Ok(())
580	}
581	
582	/// At-rest publish state of a bookmark vs its `@origin` counterpart.
583	#[derive(Debug, PartialEq, Eq)]
584	pub enum PublishState {
585	    /// Local bookmark and `bookmark@origin` point at the same commit.
586	    InSync,
587	    /// `bookmark@origin` does not exist — never pushed.
588	    NeverPushed,
589	    /// Local and origin point at different commits (full commit ids).
590	    Mismatch { local: String, remote: String },
591	}
592	
593	/// Resolve the at-rest publish state of `bookmark` in `repo`.
594	///
595	/// The bookmark only moves inside a push / squash-push run, which
596	/// publishes it in the same invocation — so between commands
597	/// `bookmark == bookmark@origin` is the invariant. A mismatch means
598	/// an earlier publish was lost (or origin moved out from under us).
599	///
600	/// - Read-only: two facade commit-id lookups, nothing else.
601	/// - Errors when the local bookmark itself does not resolve.
602	pub fn bookmark_publish_state(
603	    repo: &Path,
604	    bookmark: &str,
605	) -> Result<PublishState, Box<dyn std::error::Error>> {
606	    let repo_str = repo.to_string_lossy();
607	    let commit_id = |rev: &str| crate::jj::cid_of(repo, rev);
608	    let local = commit_id(bookmark)
609	        .map_err(|e| format!("bookmark '{bookmark}' does not resolve in '{repo_str}': {e}"))?;
610	    // `present(...)` maps a nonexistent remote bookmark to an empty
611	    // result instead of a revset error.
612	    let remote = commit_id(&format!("present({bookmark}@origin)"))?;
613	    Ok(if remote.is_empty() {
614	        PublishState::NeverPushed
615	    } else if local == remote {
616	        PublishState::InSync
617	    } else {
618	        PublishState::Mismatch { local, remote }
619	    })
620	}
621	
622	/// Verify the bot repo's `bookmark` is published at origin.
623	///
624	/// Error-raising wrapper over [`bookmark_publish_state`], used by
625	/// `validate-bot` and push preflight. Fixes nothing (decided
626	/// 2026-07-15: no automatic fixing) — the error names the
627	/// `vc-x1 squash-push` resolution and the caller stops.
628	pub fn verify_bot_published(
629	    bot_repo: &Path,
630	    bookmark: &str,
631	) -> Result<(), Box<dyn std::error::Error>> {
632	    let repo_str = bot_repo.to_string_lossy();
633	    match bookmark_publish_state(bot_repo, bookmark)? {
634	        PublishState::InSync => Ok(()),
635	        PublishState::NeverPushed => Err(format!(
636	            "bot repo '{repo_str}': bookmark '{bookmark}' has never been pushed to origin — \
637	             publish it with `vc-x1 squash-push -R {repo_str}`"
638	        )
639	        .into()),
640	        PublishState::Mismatch { local, remote } => Err(format!(
641	            "bot repo '{repo_str}': '{bookmark}' ({}) does not match '{bookmark}@origin' ({}) — \
642	             an earlier publish was likely lost; publish it with \
643	             `vc-x1 squash-push -R {repo_str}`, then retry",
644	            &local[..local.len().min(12)],
645	            &remote[..remote.len().min(12)]
646	        )
647	        .into()),
648	    }
649	}
650	
651	/// Resolve a `[repos]` registry value against the directory of the
652	/// config file that states it.
653	///
654	/// - relative value -> joined onto `cfg_dir` (the standard
655	///   file-relative rule);
656	/// - absolute value -> taken as-is (allowed but discouraged — it
657	///   commits one machine's layout).
658	pub fn resolve_repo_path(cfg_dir: &Path, value: &str) -> PathBuf {
659	    let p = Path::new(value);
660	    if p.is_absolute() {
661	        p.to_path_buf()
662	    } else {
663	        cfg_dir.join(p)
664	    }
665	}
666	
667	/// True when `dir` is a workspace's bot repo.
668	///
669	/// Side detection is by *self-resolution*: `dir` is the bot side
670	/// iff its own `.vc-config.toml`'s `repos.bot` resolves
671	/// (file-relative) back to `dir` itself — the entry that names the
672	/// config's own directory names the side. Falls back to the
673	/// legacy location rule ([`legacy_is_bot_dir`]) so read-only
674	/// surfaces that bypass the resolvers' legacy rejection (explicit
675	/// `--other-repo` paths in validate-desc / fix-desc) still see a
676	/// legacy bot dir as the bot side. Paths are canonicalized so
677	/// relative forms and symlinked tempdirs compare correctly;
678	/// anything unreadable is "not the bot side".
679	pub fn is_bot_dir(dir: &Path) -> bool {
680	    let Ok(dir) = dir.canonicalize() else {
681	        return false;
682	    };
683	    if let Ok(cfg) = toml_simple::toml_load(&dir.join(VC_CONFIG_FILE))
684	        && let Some(bot) = toml_simple::toml_get(&cfg, "repos.bot").filter(|v| !v.is_empty())
685	    {
686	        return resolve_repo_path(&dir, bot)
687	            .canonicalize()
688	            .is_ok_and(|p| p == dir);
689	    }
690	    crate::legacy_vc_config::is_bot_dir(&dir)
691	}
692	
693	/// Walk up from `start` to find the workspace root (the work repo).
694	///
695	/// The nearest ancestor with a `.vc-config.toml` decides: its
696	/// `repos.work`, resolved file-relative, *is* the root — the walk
697	/// finding the bot repo's config first still lands on the work
698	/// repo (its `work` points there), so the two sides need no
699	/// nesting assumption. Returns `None` if no config is found up to
700	/// the filesystem root — the caller is in a "plain old repo" (POR)
701	/// with no vc-x1 workspace metadata.
702	///
703	/// Legacy roots — the 0.75.x root-anchored `[workspace] work`
704	/// schema and the pre-0.75.0 `path = "/"` schema — are still
705	/// *found* (pointed at the work side via the legacy location
706	/// rule), so the resolvers can reject them with a fix-it message
707	/// via `reject_legacy_config` instead of silently degrading the
708	/// workspace to POR.
709	pub fn find_workspace_root_from(start: &Path) -> Option<PathBuf> {
710	    let mut cur = start.to_path_buf();
711	    loop {
712	        let cfg = cur.join(VC_CONFIG_FILE);
713	        if let Ok(map) = toml_simple::toml_load(&cfg) {
714	            if let Some(work) = toml_simple::toml_get(&map, "repos.work") {
715	                let resolved = resolve_repo_path(&cur, work);
716	                // OK: a declared-but-missing work dir surfaces at
717	                // the resolvers' coherence checks, not here.
718	                return Some(resolved.canonicalize().unwrap_or(resolved));
719	            }
720	            if crate::legacy_vc_config::is_root_marker(&map) {
721	                return if crate::legacy_vc_config::is_bot_dir(&cur) {
722	                    cur.parent().map(Path::to_path_buf)
723	                } else {
724	                    Some(cur)
725	                };
726	            }
727	        }
728	        cur = cur.parent()?.to_path_buf();
729	    }
730	}
731	
732	/// Error fast on a legacy `.vc-config.toml` schema.
733	///
734	/// The topology readers treat unknown keys as absent, which would
735	/// silently degrade a dual workspace to single-repo — so every
736	/// resolver calls this first and fails with the
737	/// [`legacy_vc_config::reject`](crate::legacy_vc_config::reject)
738	/// rewrite instead. A config with both a `[repos]` registry and
739	/// stray legacy keys passes (the registry drives behavior;
740	/// `config --validate` flags the strays). Also rejects an empty
741	/// `repos.work` — every reader would silently misresolve it.
742	pub fn reject_legacy_config(dir: &Path) -> Result<(), Box<dyn std::error::Error>> {
743	    let Ok(cfg) = toml_simple::toml_load(&dir.join(VC_CONFIG_FILE)) else {
744	        return Ok(());
745	    };
746	    if let Some(msg) = crate::legacy_vc_config::reject(dir, &cfg) {
747	        return Err(msg.into());
748	    }
749	    if toml_simple::toml_get(&cfg, "repos.work").is_some_and(|w| w.is_empty()) {
750	        return Err(format!(
751	            "{}/.vc-config.toml: repos.work is empty — it must be a path \
752	             (relative to the config file's directory, e.g. \".\" in the \
753	             work repo); nothing was changed",
754	            dir.display()
755	        )
756	        .into());
757	    }
758	    Ok(())
759	}
760	
761	/// Cwd-anchored wrapper over [`find_workspace_root_from`].
762	pub fn find_workspace_root() -> Option<PathBuf> {
763	    let cur = std::env::current_dir().ok()?;
764	    find_workspace_root_from(&cur)
765	}
766	
767	/// Resolve the workspace's default `--scope`.
768	///
769	/// Reads `<workspace_root>/.vc-config.toml > repos.bot`:
770	///
771	/// - dual workspace (non-empty `bot`) -> `Scope([Work, Bot])`
772	/// - single-repo workspace (missing / empty `bot`) ->
773	///   `Scope([Work])`
774	/// - POR (no `workspace_root`) -> `Scope([Work])` — `scope_to_repos`
775	///   resolves `Side::Work` to cwd's `.` when no root is given, so a
776	///   POR run still operates on the current directory.
777	pub fn default_scope(workspace_root: Option<&Path>) -> Scope {
778	    let Some(root) = workspace_root else {
779	        return Scope(vec![Side::Work]);
780	    };
781	    let cfg = match toml_simple::toml_load(&root.join(VC_CONFIG_FILE)) {
782	        Ok(c) => c,
783	        Err(_) => return Scope(vec![Side::Work]),
784	    };
785	    match toml_simple::toml_get(&cfg, "repos.bot") {
786	        Some(v) if !v.is_empty() => Scope(vec![Side::Work, Side::Bot]),
787	        _ => Scope(vec![Side::Work]),
788	    }
789	}
790	
791	/// Resolve a `Scope` to concrete repo paths.
792	///
793	/// - `Side::Work` -> `workspace_root` (or cwd's `.` when
794	///   `workspace_root` is None).
795	/// - `Side::Bot` -> the root config's `repos.bot`, resolved
796	///   file-relative against the root.
797	///
798	/// Errors when `Side::Bot` is requested but the workspace doesn't
799	/// define one (POR or single-repo workspace).
800	pub fn scope_to_repos(
801	    scope: &Scope,
802	    workspace_root: Option<&Path>,
803	) -> Result<Vec<PathBuf>, Box<dyn std::error::Error>> {
804	    if let Some(root) = workspace_root {
805	        reject_legacy_config(root)?;
806	    }
807	    let mut repos = Vec::new();
808	    for side in &scope.0 {
809	        match side {
810	            Side::Work => repos.push(
811	                workspace_root
812	                    .map(Path::to_path_buf)
813	                    .unwrap_or_else(|| PathBuf::from(".")),
814	            ),
815	            Side::Bot => {
816	                let root = workspace_root.ok_or(
817	                    "--scope=bot: not in a vc-x1 workspace (no .vc-config.toml with a [repos] registry) — drop --scope or use --scope=work",
818	                )?;
819	                let cfg = toml_simple::toml_load(&root.join(VC_CONFIG_FILE))?;
820	                let bot = toml_simple::toml_get(&cfg, "repos.bot")
821	                    .filter(|v| !v.is_empty())
822	                    .ok_or(
823	                        "--scope=bot: no bot repo configured. Add `bot = \"...\"` to the [repos] registry to enable dual-repo operations",
824	                    )?;
825	                repos.push(resolve_repo_path(root, bot));
826	            }
827	        }
828	    }
829	    Ok(repos)
830	}
831	
832	/// Resolve the workspace's bot-repo path, or `None` when it has no
833	/// bot side.
834	///
835	/// The scope-aware prelude for commands that *optionally* work
836	/// against the bot repo (validate-desc / fix-desc): topology comes
837	/// from `default_scope` (the workspace config), not a flag —
838	/// `Ok(None)` means a POR / single-repo workspace, the caller's
839	/// no-op case, while a configured-but-broken bot side still errors
840	/// via `scope_to_repos`.
841	pub fn bot_repo_path(workspace_root: &Path) -> Result<Option<PathBuf>, Box<dyn std::error::Error>> {
842	    match configured_bot_dir(workspace_root)? {
843	        Some(bot) => {
844	            verify_workspace_coherence(workspace_root, &bot)?;
845	            Ok(Some(bot))
846	        }
847	        None => Ok(None),
848	    }
849	}
850	
851	/// The bot dir the workspace config *declares* — a pure config
852	/// read, no on-disk verification.
853	///
854	/// The pre-coherence half of [`bot_repo_path`], for callers that
855	/// resolve the dir before it exists (clone names the local clone
856	/// destination from the just-cloned work repo's config). `Ok(None)`
857	/// when the workspace declares no bot side.
858	pub fn configured_bot_dir(
859	    workspace_root: &Path,
860	) -> Result<Option<PathBuf>, Box<dyn std::error::Error>> {
861	    reject_legacy_config(workspace_root)?;
862	    if !default_scope(Some(workspace_root)).has_bot() {
863	        return Ok(None);
864	    }
865	    let repos = scope_to_repos(&Scope(vec![Side::Bot]), Some(workspace_root))?;
866	    match repos.as_slice() {
867	        [bot] => Ok(Some(bot.clone())),
868	        other => Err(format!(
869	            "configured_bot_dir: expected one repo from scope_to_repos, got {}",
870	            other.len()
871	        )
872	        .into()),
873	    }
874	}
875	
876	/// Resolve the bot repo of a workspace that *requires* one.
877	///
878	/// The dual-only sibling of [`bot_repo_path`] for operations that
879	/// make no sense without a bot side (push): `None` becomes a loud
880	/// error instead of a no-op signal.
881	pub fn require_bot_dir(workspace_root: &Path) -> Result<PathBuf, Box<dyn std::error::Error>> {
882	    bot_repo_path(workspace_root)?.ok_or_else(|| {
883	        format!(
884	            "{}/.vc-config.toml declares no bot repo (`repos.bot`) — \
885	             this operation requires a dual workspace",
886	            workspace_root.display()
887	        )
888	        .into()
889	    })
890	}
891	
892	/// Dual-mode entry preflight: verify the two repos' recorded
893	/// topology agrees before any operation acts on it.
894	///
895	/// Checks, in order, erroring with everything known and changing
896	/// nothing (the dual-preflight principle, 2026-07-23):
897	///
898	/// - the bot dir exists (and is a directory);
899	/// - its `.vc-config.toml` loads;
900	/// - **resolved agreement**: each side's declared `[repos]` pair,
901	///   resolved file-relative and canonicalized, names the same two
902	///   directories (the file-relative schema makes the raw blocks
903	///   asymmetric by design, so agreement is checked on resolved
904	///   reality, not spelling);
905	/// - **self-identification**: each config's own directory sits at
906	///   its side's key (root's `work`, bot's `bot`) — agreement
907	///   alone can't catch both sides naming the same wrong pair.
908	///
909	/// Mid-flight surprises stay per-operation concerns; this gates
910	/// *entry* at the one topology resolver.
911	fn verify_workspace_coherence(root: &Path, bot: &Path) -> Result<(), Box<dyn std::error::Error>> {
912	    if !bot.is_dir() {
913	        return Err(format!(
914	            "workspace incoherent: {}/.vc-config.toml declares bot repo '{}', \
915	             but that directory does not exist — fix the `bot` value or \
916	             restore the directory; nothing was changed",
917	            root.display(),
918	            bot.display()
919	        )
920	        .into());
921	    }
922	    let root_cfg = toml_simple::toml_load(&root.join(VC_CONFIG_FILE))?;
923	    let bot_cfg = toml_simple::toml_load(&bot.join(VC_CONFIG_FILE)).map_err(|e| {
924	        format!(
925	            "workspace incoherent: bot repo '{}' has no readable {VC_CONFIG_FILE} \
926	             ({e}) — both sides must carry a [repos] registry naming the same \
927	             directories; nothing was changed",
928	            bot.display()
929	        )
930	    })?;
931	    let (root_pair, bot_pair) = (
932	        resolved_repos_pair(root, &root_cfg)?,
933	        resolved_repos_pair(bot, &bot_cfg)?,
934	    );
935	    if root_pair != bot_pair {
936	        return Err(format!(
937	            "workspace incoherent: the two sides' [repos] registries resolve to \
938	             different directories — they must name the same work/bot pair; \
939	             nothing was changed\n\
940	             {}/{VC_CONFIG_FILE}: work={}, bot={}\n\
941	             {}/{VC_CONFIG_FILE}: work={}, bot={}",
942	            root.display(),
943	            root_pair.0.display(),
944	            root_pair.1.display(),
945	            bot.display(),
946	            bot_pair.0.display(),
947	            bot_pair.1.display()
948	        )
949	        .into());
950	    }
951	    // Self-identification: agreement alone can't catch both sides
952	    // naming the same *wrong* pair — each config's own directory
953	    // must sit at its side's key.
954	    let canon_root = root.canonicalize()?;
955	    if root_pair.0 != canon_root {
956	        return Err(format!(
957	            "workspace incoherent: {}/{VC_CONFIG_FILE}'s `repos.work` resolves to \
958	             '{}', not to the workspace root itself — the work side's own entry \
959	             must name its own directory; nothing was changed",
960	            root.display(),
961	            root_pair.0.display()
962	        )
963	        .into());
964	    }
965	    let canon_bot = bot.canonicalize()?;
966	    if bot_pair.1 != canon_bot {
967	        return Err(format!(
968	            "workspace incoherent: {}/{VC_CONFIG_FILE}'s `repos.bot` resolves to \
969	             '{}', not to the bot repo itself — the bot side's own entry must \
970	             name its own directory; nothing was changed",
971	            bot.display(),
972	            bot_pair.1.display()
973	        )
974	        .into());
975	    }
976	    Ok(())
977	}
978	
979	/// Resolve and canonicalize one side's declared `[repos]` pair.
980	///
981	/// The per-side half of the resolved-agreement check: reads
982	/// `repos.work` / `repos.bot` from `cfg` (the config at
983	/// `cfg_dir`), resolves each file-relative, and canonicalizes —
984	/// a missing key or unresolvable directory is its own coherence
985	/// error.
986	fn resolved_repos_pair(
987	    cfg_dir: &Path,
988	    cfg: &HashMap<String, String>,
989	) -> Result<(PathBuf, PathBuf), Box<dyn std::error::Error>> {
990	    let resolve = |key: &str| -> Result<PathBuf, Box<dyn std::error::Error>> {
991	        let value = toml_simple::toml_get(cfg, key)
992	            .filter(|v| !v.is_empty())
993	            .ok_or_else(|| {
994	                format!(
995	                    "workspace incoherent: {}/{VC_CONFIG_FILE} has no `{key}` in its \
996	                     [repos] registry — both sides must declare the work/bot pair; \
997	                     nothing was changed",
998	                    cfg_dir.display()
999	                )
1000	            })?;
1001	        resolve_repo_path(cfg_dir, value)
1002	            .canonicalize()
1003	            .map_err(|e| {
1004	                format!(
1005	                    "workspace incoherent: {}/{VC_CONFIG_FILE}'s `{key}` (\"{value}\") does \
1006	                 not resolve to an existing directory ({e}); nothing was changed",
1007	                    cfg_dir.display()
1008	                )
1009	                .into()
1010	            })
1011	    };
1012	    Ok((resolve("repos.work")?, resolve("repos.bot")?))
1013	}
1014	
1015	/// Resolve `CommonArgs.repo` + `CommonArgs.scope` into concrete repo paths.
1016	///
1017	/// The four `CommonArgs` consumers (`chid` / `desc` / `list` / `show`)
1018	/// call this at the start of their body to translate the clap surface
1019	/// into the `&[PathBuf]` that `for_each_repo` iterates. Behavior matches
1020	/// today's defaults plus a composing rule for the new `--scope` flag:
1021	///
1022	/// - neither flag -> `[.]` (today's no-arg default).
1023	/// - `-R PATH` alone -> `[PATH]` (today's `-R <path>` behavior;
1024	///   workspace context not consulted).
1025	/// - `-s ROLES` alone -> resolves against `find_workspace_root()` —
1026	///   the surrounding workspace if there is one, else POR
1027	///   (`Side::Work` -> `.`, `Side::Bot` -> error).
1028	/// - `-R PATH -s ROLES` -> resolves with `PATH` as the workspace root
1029	///   (overrides `find_workspace_root`). This is the composing case;
1030	///   e.g. `chid -R ../foo -s bot` queries `../foo/.claude`.
1031	///
1032	/// `--scope` is keyword-only (`work|bot|work,bot|bot,work`);
1033	/// path-based single-repo operation routes through `-R/--repo`.
1034	pub fn resolve_repos(
1035	    repo: Option<&Path>,
1036	    scope: Option<&Scope>,
1037	) -> Result<Vec<PathBuf>, Box<dyn std::error::Error>> {
1038	    match (repo, scope) {
1039	        (None, None) => Ok(vec![PathBuf::from(".")]),
1040	        (Some(p), None) => Ok(vec![p.to_path_buf()]),
1041	        (Some(p), Some(s)) => scope_to_repos(s, Some(p)),
1042	        (None, Some(s)) => scope_to_repos(s, find_workspace_root().as_deref()),
1043	    }
1044	}
1045	
1046	/// Resolved shared params for the read-only commit-query subcommands
1047	/// (`chid` / `desc` / `list` / `show`). Built once at the binary edge
1048	/// from `CommonArgs` via `TryFrom`; each subcommand's `XxxParams`
1049	/// embeds this.
1050	///
1051	/// - `spec` — resolved `DotSpec` (parsed `..` notation + per-side
1052	///   count budget).
1053	/// - `header` — resolved inter-repo `Header` (label vs none).
1054	/// - `repos` — resolved repo paths (`-R` + `-s` -> `Vec<PathBuf>`).
1055	#[derive(Debug)]
1056	pub struct CommonParams {
1057	    pub spec: DotSpec,
1058	    pub header: Header,
1059	    pub repos: Vec<PathBuf>,
1060	}
1061	
1062	impl TryFrom<&CommonArgs> for CommonParams {
1063	    type Error = String;
1064	
1065	    /// Resolve clap `CommonArgs` into clap-free `CommonParams`: run
1066	    /// `resolve_spec` / `resolve_header` / `resolve_repos` at the
1067	    /// binary edge. Fallible because `resolve_repos` can fail
1068	    /// (workspace lookup, path issues).
1069	    fn try_from(a: &CommonArgs) -> Result<Self, String> {
1070	        let spec = resolve_spec(a.pos_rev.as_deref(), a.pos_count, &a.revision, a.limit, "@");
1071	        let header = resolve_header(&a.label, a.no_label);
1072	        let repos = a.resolve_repos().map_err(|e| e.to_string())?;
1073	        Ok(CommonParams {
1074	            spec,
1075	            header,
1076	            repos,
1077	        })
1078	    }
1079	}
