use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use crate::desc_helpers::VC_CONFIG_FILE;
use crate::options_flags::common_args::CommonArgs;
use crate::options_flags::scope::{Scope, Side};
use crate::toml_simple;
