1	//! Repo lifecycle helpers — creation, finalization, cross-references.
2	//!
3	//! Sibling of `url` (URL/target parsing); this module hosts the
4	//! local-state mechanics that don't depend on URL form. As of
5	//! 0.41.1-6.5:
6	//!
7	//! - `prepare_local_repo` — mkdir, colocated jj init, optional
8	//!   template copy. Leaves the working copy uncommitted.
9	//! - `commit_initial` — jj commit of the prepared tree; returns
10	//!   its chid.
11	//! - `cross_ref_ochids` — rewrite both initial commits' placeholder
12	//!   `ochid: /none` trailers once each side's chid is known.
13	//! - `OchidStrategy` — initial-commit message policy.
14	//!
15	//! Splitting prepare from commit lets callers write role-specific
16	//! files (`.vc-config.toml`, `.gitignore`) into the prepared tree
17	//! before the initial commit captures them.
18	
19	use std::path::Path;
20	
21	use log::{debug, info};
22	
23	use crate::common::{mkdir_p, run};
24	use crate::init::{copy_template_recursive, rewrite_readme_first_line};
25	use crate::jj;
26	
27	/// Initial-commit ochid policy used by `commit_initial`.
28	///
29	/// - `None` — POR: plain `Initial commit` message.
30	/// - `Placeholder` — Dual: `Initial commit\n\nochid: /none`,
31	///   rewritten via cross-ref `jj describe` once both sides have
32	///   committed and their chids are known.
33	#[derive(Clone, Copy, Debug)]
34	pub enum OchidStrategy {
35	    None,
36	    Placeholder,
37	}
38	
39	/// Prepare a fresh local repo at `target`: directory + git/jj
40	/// init + optional template copy. The working copy is left
41	/// uncommitted so callers can drop role-specific files (e.g.
42	/// `.vc-config.toml`, `.gitignore`) into the tree before
43	/// `commit_initial` captures them in the initial commit.
44	///
45	/// Performs:
46	/// - Creates `target` (and its parent if needed).
47	/// - `jj git init --colocate` (which creates the git repo too).
48	/// - Optionally copies a template tree, rewriting any
49	///   `README.md`'s first line to `# <name>`.
50	///
51	/// Parameters:
52	/// - `target` — destination directory for the new repo. Created
53	///   (along with its parent if needed); must not already exist
54	///   as a populated repo.
55	/// - `info_label` — narration tag (`"work"`, `"bot"`, `"scratch"`,
56	///   etc.); appears in `info!()` lines.
57	/// - `template` — optional source dir. When present, copied
58	///   recursively (non-hidden only) and any `README.md`'s first
59	///   line is rewritten to `# <name>`.
60	/// - `name` — repo name used by the README rewrite.
61	pub fn prepare_local_repo(
62	    target: &Path,
63	    info_label: &str,
64	    template: Option<&Path>,
65	    name: &str,
66	) -> Result<(), Box<dyn std::error::Error>> {
67	    info!(
68	        "Preparing local repo {info_label} directory at {}",
69	        target.display()
70	    );
71	
72	    if let Some(parent) = target.parent() {
73	        mkdir_p(parent)?;
74	    }
75	    mkdir_p(target)?;
76	
77	    // `jj git init --colocate` creates the git repo itself — the
78	    // former explicit `git init` was redundant (0.76.0-5).
79	    info!("Initializing {info_label} repo (jj, colocated)...");
80	    run("jj", &["git", "init", "--colocate"], target)?;
81	
82	    if let Some(t) = template {
83	        info!(
84	            "Copying {info_label} template: {} -> {}",
85	            t.display(),
86	            target.display()
87	        );
88	        copy_template_recursive(t, target)?;
89	        rewrite_readme_first_line(target, name)?;
90	    }
91	
92	    Ok(())
93	}
94	
95	/// Commit the prepared working copy as an initial commit and
96	/// return its chid (`jj @-`).
97	///
98	/// Pairs with `prepare_local_repo`: caller calls `prepare_local_repo`,
99	/// optionally writes role-specific files (e.g. `.vc-config.toml`,
100	/// `.gitignore`) into the tree, then calls this to capture the
101	/// whole snapshot in the initial commit.
102	///
103	/// Parameters:
104	/// - `target` — repo working dir, already prepared.
105	/// - `info_label` — narration tag, mirroring `prepare_local_repo`.
106	/// - `ochid_strategy` — message policy: `None` writes a plain
107	///   `Initial commit`; `Placeholder` writes
108	///   `Initial commit\n\nochid: /none` for later rewrite by
109	///   `cross_ref_ochids`.
110	pub fn commit_initial(
111	    target: &Path,
112	    info_label: &str,
113	    ochid_strategy: OchidStrategy,
114	) -> Result<String, Box<dyn std::error::Error>> {
115	    let msg = match ochid_strategy {
116	        OchidStrategy::None => "Initial commit",
117	        OchidStrategy::Placeholder => "Initial commit\n\nochid: /none",
118	    };
119	    info!("Committing {info_label}...");
120	    jj::commit(target, msg)?;
121	
122	    let chid = jj::chid_of(target, "@-")?;
123	    info!(
124	        "Committed {info_label} initial at {} chid = {chid}",
125	        target.display()
126	    );
127	    Ok(chid)
128	}
129	
130	/// Rewrite the placeholder `ochid: /none` trailers on both sides
131	/// of a dual-repo workspace so each initial commit points at its
132	/// counterpart's chid (init step 6).
133	///
134	/// Both sides must already have an initial commit shaped by
135	/// `OchidStrategy::Placeholder`. After the rewrite, each commit's
136	/// ochid trailer is a workspace-root-relative path: the work side
137	/// points at `/.claude/<bot_chid>`; the bot side points at
138	/// `/<work_chid>`.
139	///
140	/// Parameters:
141	/// - `work_dir` — work repo on disk; receives `/.claude/<chid>`.
142	/// - `work_chid` — work-side initial-commit chid; embedded into
143	///   the bot-side trailer.
144	/// - `bot_dir` — bot repo on disk; receives `/<chid>`.
145	/// - `bot_chid` — bot-side initial-commit chid; embedded
146	///   into the work-side trailer.
147	pub fn cross_ref_ochids(
148	    work_dir: &Path,
149	    work_chid: &str,
150	    bot_dir: &Path,
151	    bot_chid: &str,
152	) -> Result<(), Box<dyn std::error::Error>> {
153	    info!("Setting ochid cross-references...");
154	    // The bot-side ochid prefix is the bot dir's workspace-relative
155	    // path (`/<dir-name>`), derived from the dir init just created.
156	    let bot_name = bot_dir
157	        .file_name()
158	        .ok_or_else(|| {
159	            format!(
160	                "cross_ref_ochids: bot dir '{}' has no name",
161	                bot_dir.display()
162	            )
163	        })?
164	        .to_string_lossy();
165	    let work_desc = format!("Initial commit\n\nochid: /{bot_name}/{bot_chid}");
166	    let bot_desc = format!("Initial commit\n\nochid: /{work_chid}");
167	
168	    debug!("work side: rewrite initial commit's ochid to point at bot chid");
169	    jj::describe(work_dir, "@-", &work_desc)?;
170	    debug!("bot side: rewrite initial commit's ochid to point at work chid");
171	    jj::describe(bot_dir, "@-", &bot_desc)?;
172	
173	    debug!("surface post-describe git hashes for the debug log");
174	    let hash = run("git", &["rev-parse", "HEAD"], work_dir)?;
175	    debug!("work repo: chid={work_chid} hash={hash}");
176	    let hash = run("git", &["rev-parse", "HEAD"], bot_dir)?;
177	    debug!(".claude:   chid={bot_chid} hash={hash}");
178	    Ok(())
179	}
180	
181	#[cfg(test)]
182	mod tests {
183	    use super::*;
184	
185	    /// `OchidStrategy::None` produces a plain `Initial commit`
186	    /// message (POR-shape).
187	    #[test]
188	    fn strategy_none_writes_plain_commit() {
189	        let base = crate::test_helpers::unique_base("create-repo-strategy-none");
190	        let target = base.join("work");
191	        std::fs::create_dir_all(&base).expect("mkdir base");
192	
193	        prepare_local_repo(&target, "work", None, "scratch").expect("prepare_local_repo");
194	        let chid = commit_initial(&target, "work", OchidStrategy::None).expect("commit_initial");
195	
196	        assert!(!chid.is_empty(), "chid returned");
197	        assert!(target.join(".jj").exists(), "jj initialized");
198	        assert!(target.join(".git").exists(), "git initialized");
199	
200	        let log = run("git", &["log", "-1", "--format=%B"], &target).expect("git log");
201	        assert_eq!(
202	            log.trim(),
203	            "Initial commit",
204	            "OchidStrategy::None uses a plain message"
205	        );
206	
207	        let _ = std::fs::remove_dir_all(&base);
208	    }
209	
210	    /// `OchidStrategy::Placeholder` writes the `ochid: /none`
211	    /// placeholder in the initial commit message — what dual mode
212	    /// lands before the cross-ref rewrite in step 6.
213	    #[test]
214	    fn strategy_placeholder_writes_ochid_none() {
215	        let base = crate::test_helpers::unique_base("create-repo-strategy-placeholder");
216	        let target = base.join("work");
217	        std::fs::create_dir_all(&base).expect("mkdir base");
218	
219	        prepare_local_repo(&target, "work", None, "scratch").expect("prepare_local_repo");
220	        let _chid =
221	            commit_initial(&target, "work", OchidStrategy::Placeholder).expect("commit_initial");
222	
223	        let log = run("git", &["log", "-1", "--format=%B"], &target).expect("git log");
224	        assert!(log.contains("Initial commit"));
225	        assert!(
226	            log.contains("ochid: /none"),
227	            "OchidStrategy::Placeholder leaves a placeholder ochid trailer"
228	        );
229	
230	        let _ = std::fs::remove_dir_all(&base);
231	    }
232	
233	    /// Neither `prepare_local_repo` nor `commit_initial` writes
234	    /// `.vc-config.toml` or `.gitignore` — those are role-specific
235	    /// and the caller drops them between prepare and commit.
236	    /// Verifies the tree contains only `.jj/` and `.git/`.
237	    #[test]
238	    fn lifecycle_does_not_write_vc_config_or_gitignore() {
239	        let base = crate::test_helpers::unique_base("create-repo-no-files");
240	        let target = base.join("work");
241	        std::fs::create_dir_all(&base).expect("mkdir base");
242	
243	        prepare_local_repo(&target, "scratch", None, "scratch").expect("prepare_local_repo");
244	        let _chid =
245	            commit_initial(&target, "scratch", OchidStrategy::None).expect("commit_initial");
246	
247	        assert!(target.join(".jj").exists(), "jj still initialized");
248	        assert!(target.join(".git").exists(), "git still initialized");
249	        assert!(
250	            !target.join(".vc-config.toml").exists(),
251	            "lifecycle does not write .vc-config.toml"
252	        );
253	        assert!(
254	            !target.join(".gitignore").exists(),
255	            "lifecycle does not write .gitignore"
256	        );
257	
258	        let _ = std::fs::remove_dir_all(&base);
259	    }
260	}
