//! The `validate-desc` subcommand: scan a revision range and check
//! each commit's `ochid:` trailer against the cross-referenced
//! repo — flagging missing, malformed, or dangling links.
//!
//! Read-only diagnostic; exits non-zero if any commit has issues.
//! The bot's "did the ochid wiring stay consistent?" check.

use std::path::PathBuf;

use clap::Args;
use jj_lib::object_id::ObjectId;
use jj_lib::repo::Repo;

use log::{debug, info};

use crate::common;
use crate::context::Context;
use crate::desc_helpers::{
    DEFAULT_ID_LEN, TitleMatch, extract_bare_id, find_matching_commit, ochid_prefix_for,
    validate_ochid,
};
use crate::subcommand::SubcommandRunner;

#[derive(Args, Debug)]
pub struct ValidateDescArgs {
    /// Revision (with optional .. notation)
    #[arg(value_name = "REVISION")]
    pub pos_rev: Option<String>,

    /// Number of commits (per open side)
    #[arg(value_name = "COMMITS")]
    pub pos_count: Option<usize>,

    /// Revision(s) to scan
    #[arg(short, long, default_value = "@")]
    pub revision: String,

    /// Number of commits to scan
    #[arg(short = 'n', long = "commits", value_name = "COMMITS")]
    pub limit: Option<usize>,

    /// Path to jj repo
    #[arg(short = 'R', long, default_value = ".")]
    pub repo: PathBuf,

    /// Path to the other repo [default: from .vc-config.toml]
    #[arg(long = "other-repo")]
    pub other_repo: Option<PathBuf>,

    /// Expected changeID length
    #[arg(long = "id-len", default_value_t = DEFAULT_ID_LEN)]
    pub id_len: usize,
}

/// Inputs to the validate-desc op, flat, owned, clap-free.
///
/// Mirrors `ValidateDescArgs`: positional `REVISION` / `COMMITS`
/// (`pos_rev` / `pos_count`), `--revision` / `--commits`
/// (`revision` / `limit`), `--repo`, `--other-repo`, `--id-len`.
pub struct ValidateDescParams {
    pub pos_rev: Option<String>,
    pub pos_count: Option<usize>,
    pub revision: String,
    pub limit: Option<usize>,
    pub repo: PathBuf,
    pub other_repo: Option<PathBuf>,
    pub id_len: usize,
}

impl From<&ValidateDescArgs> for ValidateDescParams {
    /// Convert clap-derived `ValidateDescArgs` into the flat
    /// `ValidateDescParams` (total — every field copies straight over).
    fn from(a: &ValidateDescArgs) -> Self {
        Self {
            pos_rev: a.pos_rev.clone(),
            pos_count: a.pos_count,
            revision: a.revision.clone(),
            limit: a.limit,
            repo: a.repo.clone(),
            other_repo: a.other_repo.clone(),
            id_len: a.id_len,
        }
    }
}

/// Status of a single commit's ochid validation.
enum CommitStatus {
    Ok,
    Lost,                     // ochid marked as "lost" (unrecoverable)
    None_,                    // ochid marked as "none" (no counterpart)
    NeedsFixed(String),       // summary of issues
    MissingNoTitle,           // no ochid, no title to match on
    MissingNoMatch,           // no ochid, no title match in other repo
    MissingAmbiguous(usize),  // no ochid, multiple title matches
    MissingWithMatch(String), // no ochid, unique title match found
}

impl SubcommandRunner for ValidateDescArgs {
    type Params = ValidateDescParams;

    /// Delegate to the existing `From<&ValidateDescArgs>` impl
    /// above (total — never fails).
    fn to_params(&self) -> Result<Self::Params, String> {
        Ok(ValidateDescParams::from(self))
    }

    /// Run the existing `validate_desc` op.
    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        validate_desc(ctx, params)
    }
}

/// Run the `validate-desc` subcommand: scan the resolved revision
/// range and report each commit's ochid status against the other
/// repo; errors if any commit has issues.
///
/// `ctx` is unused today (validate-desc reads `.vc-config.toml`,
/// not the user config, and doesn't touch the `--log` path); it's
/// present for the uniform subcommand-layer signature.
pub fn validate_desc(
    _ctx: &Context,
    params: &ValidateDescParams,
) -> Result<(), Box<dyn std::error::Error>> {
    debug!("validate-desc: enter");
    let (workspace, repo) = common::load_repo(&params.repo)?;

    // Resolve other repo: --other-repo flag, or scope-aware
    // resolution from the workspace config. A single-repo / POR
    // workspace has no bot side — nothing to validate against, so
    // the command no-ops instead of erroring (por equalization;
    // topology from `default_scope`, not a flag).
    let other_repo_path = match &params.other_repo {
        Some(p) => p.clone(),
        None => match common::bot_repo_path(&params.repo)? {
            Some(p) => p,
            None => {
                info!("validate-desc: single-repo workspace (no bot side) — nothing to validate");
                return Ok(());
            }
        },

//! Shared `resolve_tmp_root` for unit and integration tests.
//!
//! Pulled in from two contexts:
//! - `src/test_helpers.rs` (binary's `#[cfg(test)]` unit-test
//!   harness) via `mod test_tmp_root;` declared at the crate root.
//! - `tests/common/mod.rs` (integration-test crate) via
//!   `#[path = "../../src/test_tmp_root.rs"] mod test_tmp_root;`.
//!
//! Single source of truth. Keep this file **dependency-free** —
//! pure `std::env` + `std::path::PathBuf` — so it compiles in
//! both contexts. No `crate::...` imports; the integration-test
//! crate has a different crate root and would fail to resolve
//! them.
//!
//! Future work (per `TODO.md`) extends the priority chain
//! through `~/.config/vc-x1/config.toml` and project-local
//! `.vc-config.toml`. At that point, config-loading should pass
//! its result *in* (function arg) rather than be invoked from
//! here, preserving the dependency-free constraint.

use std::path::PathBuf;

/// Resolve the parent directory for test tempdirs.
///
/// Priority: `$VC_X1_TEST_TMPDIR` (if set and non-empty) ->
/// `std::env::temp_dir()` (= `$TMPDIR` on Unix, else `/tmp`).
pub fn resolve_tmp_root() -> PathBuf {
    if let Ok(p) = std::env::var("VC_X1_TEST_TMPDIR")
        && !p.is_empty()
    {
        return PathBuf::from(p);
    }
    std::env::temp_dir()
}

/// Whether to preserve test tempdirs across `Drop`.
///
/// Returns `true` if `$VC_X1_TEST_KEEP` is set and non-empty.
/// Consulted by RAII `Drop` impls (`Fixture`, `FixturePor`,
/// `CliFixture`) to suppress tempdir cleanup for debugging:
///
/// ```bash
/// VC_X1_TEST_KEEP=1 cargo test -- --nocapture
/// ```
///
/// Pairs with `--nocapture` so the per-fixture stderr line
/// announcing the preserved path is visible.
pub fn should_keep_tempdir() -> bool {
    keep_decision(std::env::var("VC_X1_TEST_KEEP").ok().as_deref())
}

/// Pure-policy form of `should_keep_tempdir`. Takes the env-var
/// value (`None` if unset, `Some("")` if set-but-empty) and
/// returns whether to preserve. Factored out so the decision is
/// unit-testable without manipulating global env state — env
/// mutation is not thread-safe and would race with other tests
/// reading `VC_X1_TEST_KEEP` from `Drop`.
fn keep_decision(env_value: Option<&str>) -> bool {
    match env_value {
        None => false,     // env var not set
        Some("") => false, // env var set but explicitly empty
        Some(_) => true,   // any non-empty value -> preserve
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// `$VC_X1_TEST_KEEP` unset -> no preserve.
    #[test]
    fn keep_decision_unset_is_false() {
        assert!(!keep_decision(None));
    }

    /// `$VC_X1_TEST_KEEP=""` -> no preserve. Empty-string is the
    /// "set but explicitly disabled" form (matches how env vars
    /// are unset on some shells via `VAR=`).
    #[test]
    fn keep_decision_empty_is_false() {
        assert!(!keep_decision(Some("")));
    }

    /// Any non-empty value -> preserve. Aligns with the conventional
    /// env-var-as-flag pattern (`VAR=1`, `VAR=yes`, `VAR=true` —
    /// or even `VAR=0`, since the policy treats *any* non-empty
    /// value as "set").
    #[test]
    fn keep_decision_nonempty_is_true() {
