    #[derive(Parser)]
    struct Cli {
        #[command(flatten)]
        args: SyncArgs,
    }
    let cli = Cli::try_parse_from(["test", "-s", "work"]).unwrap();
    assert_eq!(cli.args.scope, Some(Scope(vec![Side::Work])));
}
